// withLhbSeatID sets the ID field of the mutation.
func withLhbSeatID(id int) lhbseatOption {
	return func(m *LhbSeatMutation) {
		var (
			err   error
			once  sync.Once
			value *LhbSeat
		)
		m.oldValue = func(ctx context.Context) (*LhbSeat, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().LhbSeat.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

